{
  "status": "SUPPORTED",
  "task_summary": "Find a compatible component, fasten it to a marked location on the workbench, and return the tool to the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The specific marked location on the workbench where the fastening must occur.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["marked_spot", "workbench_surface"],
        "required_properties": ["location", "attachment_point"]
      },
      {
        "id": "fastener_component",
        "entity_kind": "OBJECT",
        "function": "The physical component that fits and secures the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["part", "block", "connector", "bolt"],
        "required_properties": ["compatible_with_target", "manipulatable"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The reusable equipment used to perform the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "drill", "magnet", "clipper"],
        "required_properties": ["reusable", "effective_on_fastener"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the target is located and where the tool must be left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["surface", "supportive"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "fastener_component is compatible with fastening_target",
        "participant_roles": ["fastener_component", "fastening_target"]
      ,
        "required": true
      },
      {
        "id": "relation_2",
        "relation": "fastening_tool is reusable and effective for the task",
        "participant_roles": ["fastening_tool", "fastener_component"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_1",
        "operation": "fastening",
        "participant_roles": ["fastener_component", "fastening_target", "fastening_tool"],
        "operation_count": 1
      },
      {
        "id": "operation_2",
        "operation": "placement",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "marked_spot",
          "visual_description": "A specific area on the wooden workbench surface, potentially indicated by a shadow or alignment guide, though the mark itself is not clearly visible in the current views."
        }
      ],
      "fastener_component": [
        {
          "label": "yellow_blue_blocks",
          "visual_description": "Small yellow and blue rectangular blocks sitting on a dark mat/tray on the workbench."
        }
      ],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "A wooden table with two drawers underneath and a cabinet next to it."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "region_1",
        "label": "under_cabinet_drawers",
        "visual_description": "Two closed blue drawers under the workbench.",
        "reason": "Closed storage structures where tools or components might be hidden and need to be searched."
      },
      {
        "id": "region_2",
        "label": "tall_cabinet",
        "visual_description": "A tall blue cabinet standing next to the workbench.",
        "reason": "Closed storage structure that could contain tools or compatible components."
      }
    ],
    "inspection_order": [
      "region_1",
      "region_2"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
